python3 -c "
import xml.etree.ElementTree as ET
import sys

BN = '{http://www.omg.org/spec/BPMN/20100524/MODEL}'
BDI = '{http://www.omg.org/spec/BPMN/20100524/DI}'
DC = '{http://www.omg.org/spec/DD/20100524/DC}'
UP = '{http://uipath.org/schema/bpmn}'

tree = ET.parse('/work/output/artifacts/skill-bpmn-inclusive-gateway-forkjoin/NotificationFanout.bpmn')
root = tree.getroot()
errors = []

# 1. Root is definitions with BPMN namespace
assert 'definitions' in root.tag, 'Root must be definitions'
assert BN.strip('{}') in root.tag or root.tag == f'{BN}definitions', 'Missing BPMN namespace'

proc = root.find(f'{BN}process')
assert proc is not None, 'No bpmn:process found'

# Collect all elements by id
ids = {}
for el in root.iter():
    eid = el.get('id')
    if eid:
        ids[eid] = el

# Collect flow nodes and sequence flows in process
flows = {f.get('id'): f for f in proc.iter(f'{BN}sequenceFlow')}
flow_nodes = {}
for tag in ['startEvent','endEvent','exclusiveGateway','parallelGateway','inclusiveGateway',
            'eventBasedGateway','task','serviceTask','userTask','scriptTask','sendTask',
            'receiveTask','callActivity','subProcess','businessRuleTask']:
    for el in proc.iter(f'{BN}{tag}'):
        flow_nodes[el.get('id')] = el

# 2. Check BPMNDiagram exists
diagram = root.find(f'{BDI}BPMNDiagram')
assert diagram is not None, 'No BPMNDiagram found'
plane = diagram.find(f'{BDI}BPMNPlane')
assert plane is not None, 'No BPMNPlane found'

# Collect shaped/edged elements
shapes = {s.get('bpmnElement') for s in plane.findall(f'{BDI}BPMNShape')}
edges  = {e.get('bpmnElement') for e in plane.findall(f'{BDI}BPMNEdge')}

# Every flow node has a shape
for nid in flow_nodes:
    if nid not in shapes:
        errors.append(f'  MISSING SHAPE: {nid}')

# Every sequence flow has an edge
for fid in flows:
    if fid not in edges:
        errors.append(f'  MISSING EDGE: {fid}')

# 3. sourceRef/targetRef resolve
for f in flows.values():
    src = f.get('sourceRef')
    tgt = f.get('targetRef')
    if src not in ids: errors.append(f'  DANGLING sourceRef {src}')
    if tgt not in ids: errors.append(f'  DANGLING targetRef {tgt}')

# 4. Inclusive gateway: both outgoing flows have conditionExpression
for gw in proc.iter(f'{BN}inclusiveGateway'):
    out_ids = [o.text.strip() for o in gw.findall(f'{BN}outgoing')]
    in_ids  = [i.text.strip() for i in gw.findall(f'{BN}incoming')]
    if len(out_ids) >= 2:  # SPLIT: each outgoing must be conditioned
        for fid in out_ids:
            f = flows.get(fid)
            if f is None: errors.append(f'  MISSING FLOW {fid}')
            elif f.find(f'{BN}conditionExpression') is None:
                errors.append(f'  MISSING conditionExpression on split flow {fid}')
    if len(in_ids) >= 2 and len(out_ids) == 1:
        pass  # JOIN: no conditions required on single outgoing

# 5. FAKE_JOIN: no task/event with > 1 incoming flow
for nid, node in flow_nodes.items():
    inc = [i.text.strip() for i in node.findall(f'{BN}incoming')]
    tag = node.tag.replace(BN,'')
    if tag not in ('exclusiveGateway','parallelGateway','inclusiveGateway','eventBasedGateway') and len(inc) > 1:
        errors.append(f'  FAKE_JOIN: {tag}#{nid} has {len(inc)} incoming flows')

# 6. SUPERFLUOUS_GATEWAY: no gateway with exactly 1 in AND 1 out
for tag in ('exclusiveGateway','parallelGateway','inclusiveGateway','eventBasedGateway'):
    for gw in proc.iter(f'{BN}{tag}'):
        inc = [i.text.strip() for i in gw.findall(f'{BN}incoming')]
        out = [o.text.strip() for o in gw.findall(f'{BN}outgoing')]
        if len(inc) == 1 and len(out) == 1:
            errors.append(f'  SUPERFLUOUS_GATEWAY: {tag}#{gw.get(\"id\")} 1-in/1-out')

# 7. uipath:type must be child element (not attribute) on every activity/event/mapping
for el in root.iter():
    for tag in ('activity','event','mapping'):
        if el.tag == f'{UP}{tag}':
            if el.get('type'):
                errors.append(f'  RULE6 VIOLATION: {el.tag} uses type= attribute instead of child element')
            has_type_child = any(c.tag == f'{UP}type' for c in el)
            if not has_type_child:
                errors.append(f'  MISSING type child on {el.tag} id={el.get(\"id\",\"?\")}')

print('Flow nodes:', list(flow_nodes.keys()))
print('Sequence flows:', list(flows.keys()))
print('Shapes:', sorted(shapes))
print('Edges:', sorted(edges))
if errors:
    print('ERRORS:')
    for e in errors: print(e)
    sys.exit(1)
else:
    print('VALID (structural checklist passed, no blocking errors)')
